mapper.select:
select e.id ,e.summary ,e.title ,e.category ,e.storage_path ,e.is_share ,u.name as createUser
from essay e left join t_user u on u.user_id = e.create_user where e.status =0 and e.type =#{dto.type}

    and e.create_user = #{dto.userId}


    and e.is_share = #{isShare}

order by e.update_time desc
